# ---- RoleSprite (bl) ----
C bl RoleSprite MED  # extends cz; nhân vật trên bản đồ (hero/NPC/pet), tạo bởi o.a_bl(int) từ /bin/role.bin, stats a_AI[21]
F bl.e_B statCount HIGH  # static =21; new int[bl.e_B] cho a_AI (o.a(bl), o.a_bl(cv), bn)
F bl.b_B lastMoveDirection MED  # static; b_V() gán = d_B sau mỗi bước; cd khôi phục o.a_Abl[0].a_V(bl.b_B)
F bl.a_B renderMode HIGH  # 0 = ảnh tĩnh (ctor Image), 1 = animation .av (ctor bx); a(Graphics)/a_AS(int) switch
F bl.a_Image image HIGH  # ctor bl(Image): drawImage(a_Image, x, y, 33)
F bl.a_bx animSprite HIGH  # ctor bl(bx); a(Graphics) vẽ a_bx tại d_S/e_S
F bl.c_B moveSpeed HIGH  # mặc định 4; b_V() dịch d_S/e_S thêm c_B mỗi bước; biến thân chạy =5, NPC =1
F bl.a_String name HIGH  # role.bin cột 1 (o.c_AString); bn/as hiển thị tên
F bl.b_String facePath HIGH  # role.bin cột 3 "/face/1.av" (o.d_AString); ab nạp "<face>s.av"
F bl.c_String battleSpritePath HIGH  # bn: o.d_AAString[id-1][2] = team.bin cột 2 "/ft/chr1.av", nạp làm sprite chiến đấu
F bl.d_B direction HIGH  # 0 xuống(y+) 1 lên(y-) 2 trái(x-) 3 phải(x+); a_V(int) gán, b_V() di chuyển theo
F bl.h_B savedDirection MED  # cd:2356 lưu d_B trước khi NPC quay mặt nói chuyện; ae:268 a_V(h_B) khôi phục
F bl.a_AI stats HIGH  # int[21]: [0]lv [1]exp [2]expNext [3]hp [4]baseMaxHp [5]mp [6]baseMaxMp [7]baseAtk [8]baseDef [9]baseSpd [10..14]tổng maxHp/maxMp/atk/def/spd [16]điểm tự do [17..20]điểm thuộc tính
F bl.f_B jobLevel HIGH  # ci 职业等级 so sánh o.a_Abl[0].f_B; 改变职业等级 f_B++
F bl.a_AB elementValues MED  # team.bin cột 15 "0,0,10,0" (4 hệ); o.a_bl(cv) = cv.a_AB; bn chép vào actor
F bl.a_AAB attrGrowth HIGH  # [4][5] team.bin cột 16..19; ab: cộng 1 điểm thuộc tính k -> stats HP/MP/ATK/DEF/SPD += a_AAB[k][i]
F bl.g_B actorType MED  # 1 = hero id 1/2 (o.a(bl)), 2 = NPC/khác; cd: chỉ g_B==2 đi lang thang, g_B<=2 quay mặt khi nói
F bl.a_S mapWidth LOW  # = cd.a_S (mapWidth) khi tạo/rời đội; chỉ ghi, không đọc
F bl.b_S mapHeight LOW  # = cd.b_S (mapHeight); chỉ ghi, không đọc
F bl.a_AAS followTrail HIGH  # [n][x,y,dir] d_V()/e_V() dựng; o.c() đặt đồng đội theo vết a_AAS[(k+1)*o.d_B-1]
F bl.a_Z canWander HIGH  # s<N>r.bin khoá "walk"==1; o.c(bl) đặt false cho thành viên đội; g_V() chỉ bật khi a_Z
F bl.b_Z isFlying HIGH  # i_V() bật, j_V() tắt "Kết thúc bay"; ae "Đang bay không thể nói chuyện"
F bl.c_Z isRiding MED  # ae.b(int): kiểu 1 thú cưỡi (body o.g_String roleRunBodys, tốc độ 5) / 2 thuyền (tốc độ 2) bật c_Z; b_V() không gặp quái khi c_Z
F bl.d_Z isCombatant MED  # true khi có trong team.bin hoặc là pet (o.a_bl(cv)); o.a_Abl() chỉ lấy d_Z vào trận
F bl.a_Ad skills MED  # d[] dựng từ a_AS (o.a_Ad(bl,int)); o.a_Z(bl,id) tìm kỹ năng
F bl.a_AS skillIds HIGH  # team.bin cột 13 / cv.a_AS; o.a(bl,int,int) thêm id + d mới
F bl.b_AS equipIds HIGH  # team.bin cột 14 "0,0,0,0,0,0"; o.a(short[],int) -> ck[]
F bl.a_Ack equips HIGH  # ck[6] trang bị; b_I()/c_I()... cộng chỉ số ck
F bl.a_I encounterSteps MED  # seed; b_V(): random 100..199 bước rồi cd.a(false) gặp quái
F bl.e_Z isWandering MED  # g_V() bật, f_V() tắt; cd gọi h_V() khi g_B==2 && e_Z && !h_Z
F bl.f_Z noClip HIGH  # b_V(): khi f_Z chỉ kiểm biên bản đồ, bỏ va chạm; i_V() bật khi bay; ae phím 35 (debug) đảo
F bl.c_AS footBox MED  # ctor Image: {-w/2,-8,w,8}; chỉ b(Graphics) vẽ debug
F bl.d_AS bounds HIGH  # ctor: khung ảnh / bx.a_AS(); a_AS() trả về; f_S/g_S = d_AS[2]/[3]
F bl.c_S petUid HIGH  # o.a_bl(cv): = cv.b_I; o.b(bl[]) so với "GameData.myPet[j].onlyId"
F bl.g_Z isAnimating MED  # a(Graphics): g_Z && tick%2==0 -> a_bx.a(true) sang frame; ci 控制抖动 đảo g_Z
F bl.j_S targetX HIGH  # a(int,int,int) moveTo; a_V() so d_S với j_S
F bl.k_S targetY HIGH  # a(int,int,int) moveTo; a_V() so e_S với k_S
F bl.j_B targetDirection HIGH  # moveTo var3; tới đích quay về j_B nếu 0..3 ("quay hướng")
F bl.h_Z isMovingToTarget HIGH  # moveTo bật; a_V() tắt khi tới; cd mỗi tick gọi a_V() nếu h_Z
F bl.i_Z isPlayingAction HIGH  # ci 播放动作 bật; cd gọi k() khi i_Z; k() tắt khi xong
F bl.b_I actionRepeat MED  # seed; 播放动作 tham số 3 (mặc định 1), k() giảm dần
F bl.c_I actionId HIGH  # 播放动作 tham số 2 = chỉ số anim; k() so frame với a_bx.a_I(c_I)
F bl.d_I returnAction HIGH  # 播放动作 tham số 4; k() xong -> a_bx.a_V(d_I)
F bl.e_AS stepBoxes MED  # b_V(): hộp va chạm a_AS(1) dịch trước một bước để thử va chạm
F bl.a_J wanderLastTime HIGH  # h_V(): System.currentTimeMillis() lần đổi hướng trước
F bl.b_J wanderInterval HIGH  # h_V(): 2000 rồi k.b(1000,4000) ms
F bl.l_Z isWanderStepping HIGH  # h_V(): true -> b_V() mỗi tick; đổi ngẫu nhiên
M bl.a_V(int) setDirection HIGH  # d_B = var1; animation a_bx.a_V(var1)
M bl.a_V() updateMoveTo HIGH  # đi tới (j_S,k_S); xong: h_Z=false, quay j_B, ci.a(5) tiếp script
M bl.b_V() stepForward HIGH  # dịch c_B theo d_B nếu không va chạm; đếm encounterSteps cho hero
M bl.c_V() setIdleAnim MED  # nếu bx có 8 anim: anim 0..3 (đi) -> 4..7 (đứng)
M bl.a(int,int,int) moveTo MED  # seed; target x,y,dir; h_Z=true
M bl.d_V() initFollowTrail HIGH  # a_AAS = (số người-1)*o.d_B+1 điểm lùi sau lưng theo d_B
M bl.e_V() resetFollowTrail MED  # giữ điểm đầu a_AAS[0], dựng lại vết từ vị trí hiện tại (o.f_V(int) rời đội)
M bl.a_I() getSpeed HIGH  # a_AI[9] + ck.a_I() (ck "SPD+"); o.d(bl) -> a_AI[14]
M bl.b_I() getAttack MED  # seed; a_AI[7] + ck.b_I() ("ATK+"); o.d(bl) -> a_AI[12]
M bl.c_I() getDefense HIGH  # a_AI[8] + ck.c_I() ("DEF+"); -> a_AI[13]
M bl.d_I() getMaxHp HIGH  # a_AI[4] + ck.d() ("HP+"); -> a_AI[10]
M bl.j_I() getMaxMp HIGH  # a_AI[6] + ck.e() ("MP +"); -> a_AI[11]
M bl.e_I() getFreePoints HIGH  # a_AI[16]; lên cấp "Nhận 10 điểm" +10
M bl.f_I() getAttrPoints1 MED  # a_AI[17]; ab.java:143 a_AI[k+17] += điểm cộng vào thuộc tính k
M bl.g_I() getAttrPoints2 MED  # a_AI[18]
M bl.h_I() getAttrPoints3 MED  # a_AI[19]
M bl.i_I() getAttrPoints4 MED  # a_AI[20]
M bl.a(short[]) isBlocked HIGH  # va chạm tile (ca.a(...,1)), ra ngoài bản đồ, hoặc va actor khác (bj.a)
M bl.f_V() stopWander HIGH  # e_Z = false
M bl.g_V() resumeWander HIGH  # e_Z = true nếu a_Z
M bl.h_V() updateWander HIGH  # hẹn giờ ngẫu nhiên đổi hướng / đứng, gọi b_V()
M bl.i_V() startFlying HIGH  # nạp o.h_String (/av/long1|2.av, roleFlyBody), b_Z=f_Z=true
M bl.j_V() land HIGH  # "Không thể hạ cánh tại đây" nếu va chạm; "Kết thúc bay"
M bl.k() updateScriptAction HIGH  # phát anim c_I b_I lần rồi về d_I, ci.a(2)
M bl.a_bl(bl) findTalkableNear HIGH  # quét bj actor kind 1 (k.a(bl) loại trừ) giao hộp va chạm nới 5px; cd.b_bl -> nói chuyện
M bl.a_ax(bl) findChestAhead HIGH  # hộp phía trước theo d_B giao vật kind 12 (ax); cd.a_ax
M bl.a_bl(int) findRoleOnMap HIGH  # actor kind 1 có h_S == roleId; cd.a_bl(int)

# ---- PetInfo (cv) ----
C cv PetInfo HIGH  # o.a_Acv "GameData.myPet[j]"; o.b(cv) đọc /bin/petdata.bin
