F cv.a_AB elementValues HIGH  # petdata cột 2 "3007": 4 chữ số (a=10) theo thứ tự Địa/Thủy/Hỏa/Phong; as/bn vẽ 4 hệ
F cv.a_AS skillIds HIGH  # petdata cột 13 "5,1|20,2" lấy id đầu mỗi cặp; o.a(cv,int,int) thêm
F cv.a_Ad skills MED  # d[]: new d(id,1,4) (o.a_Ad(cv,int))
F cv.b_I uid HIGH  # "GameData.myPet[j].onlyId"; o.a_V(int,int) cấp k.a(b_AI)+1
F cv.b_String dropSpec LOW  # petdata cột 19 "36,5|51,3" (id vật phẩm,số lượng); chỉ chép/lưu, không đọc
F cv.b_AB refineItemIds HIGH  # petdata cột 18; ab "Tinh luyện": o.b(b_AB[0],1) rồi xoá pet
F cv.b_Z isFainted MED  # bn: hp<=0 sau trận -> true; o.a_Acv() loại b_Z; cd hồi sinh -> false
F cv.a_B ownerHeroId HIGH  # = o.e_S ("heroId" sn.bin); mọi lọc so a_B == o.e_S
F cv.a_AAB implantSlots HIGH  # [2][2] "Cấy": [k][0]=đã cấy, [k][1]=id vật phẩm; "Số lần cấy sủng vật đã đạt giới hạn"

